INSERT OR REPLACE INTO sitio (id, titulo, descripcion, titulo_pie, celular1, telefono_fijo, celular2, footer_info, correo, facebook, instagram, linkedin, youtube, tiktok, pinterest, google, galeria_inicio) VALUES (1, 'All Design Cocinas Integrales Bogotá', '<p>En All Design Cocinas Integrales, somos expertos en la fabricación y diseño de cocinas integrales en Bogotá a la medida, adaptándonos a las necesidades y preferencias de cada cliente. Nos especializamos en ofrecer soluciones innovadoras con materiales de alta calidad, garantizando espacios funcionales, estéticos y duraderos.</p>
<p>Nuestro compromiso es brindar un servicio excepcional, cumpliendo con los más altos estándares de calidad e innovación. Nos enfocamos en diseñar, fabricar e instalar cocinas integrales modernas en Bogotá, asegurando satisfacción total y cumplimiento en tiempos de entrega.</p>
<h2>Cocinas Integrales en Bogotá: Diseños a la Medida</h2>
<p>Descubre nuestro catálogo de cocinas integrales en Bogotá, con una amplia variedad de estilos y acabados para transformar tu hogar. Diseñamos espacios que combinan funcionalidad y elegancia, utilizando materiales resistentes y modernos.</p>
<p>👉 Explora nuestros diseños de cocinas aquí:<br><a href="/concinas-integrales/">Cocinas Integrales Bogotá</a></p>
<h3>Muebles para el Hogar: Complementa tu Espacio</h3>
<p>Además de nuestras cocinas integrales, ofrecemos una línea exclusiva de muebles vanguardistas para el hogar, siempre alineados con las últimas tendencias en diseño y fabricación.</p>
<ul>
<li>🔹 Closets personalizados</li>
<li>🔹 Escritorios y exhibidores modernos</li>
<li>🔹 Materiales de alta calidad</li>
</ul>
<p>En All Design Cocinas, garantizamos que cada mueble y cada cocina integral sean diseñados con precisión, asegurando espacios armoniosos, elegantes y funcionales. Nuestro enfoque en la calidad y la innovación nos permite crear ambientes que superan las expectativas de nuestros clientes en Bogotá y sus alrededores.</p>
<p>🚀 Transforma tu hogar con una cocina integral, moderna y personalizada en Bogotá. Contáctanos y haz realidad el diseño que siempre soñaste.</p>', 'All design cocinas integrales', '3162899290', '', '', 'Todos los derechos reservados ©', 'patricia.silva@alldesign.com.co', 'https://facebook.com/alldesigncocinas.com.co', '', 'https://linkedin.com/company/alldesigncocinas', 'https://www.youtube.com/@Alldesigncocinas/videos', '', '', 'https://www.google.com/maps/place/All+Design+Cocinas+Integrales+en+Bogot%C3%A1/@4.7477007,-74.1010994,17z/data=!3m1!4b1!4m6!3m5!1s0x8e3f845f8e2e3095:0x37a8b60fd6d72bf0!8m2!3d4.7477007!4d-74.0985245!16s%2Fg%2F1ptxqthfj', '[{"imagen": "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-2.webp", "alt": "Cocinas integrales Bogotá con perfil manija interna gola y graf"}, {"imagen": "cocina-moderna.webp", "alt": "Cocina moderna"}, {"imagen": "cocina-integral-en-puliuretano.webp", "alt": "Cocina integral en poliuretano"}, {"imagen": "cocinas-en-tablex-formica-cantos-en-auminio-1.webp", "alt": "Cocinas en tablex fórmica cantos en aluminio"}, {"imagen": "cocina-perfil-aluminio.webp", "alt": "Cocina perfil aluminio"}, {"imagen": "muebles-de-bano-en-tablex-rh-6.webp", "alt": "Muebles de baño en tablex RH"}, {"imagen": "mueble-de-bano.webp", "alt": "Mueble de baño"}]');

INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocina-integral-de-diseno-minimalista-con-barra-auxiliar', 'Cocina Integral de Diseño Minimalista con Barra Auxiliar', '<p>Cocina Integral de Diseño Minimalista con Barra Auxiliar</p>
<p>Presentamos este proyecto de cocina integral donde la funcionalidad y la estética moderna se encuentran. El diseño se caracteriza por sus gabinetes superiores en acabado madera e inferiores en tono gris neutro, ambos con un sistema de apertura sin manijas (tipo gola o push-to-open) que asegura una superficie limpia y visualmente continua.</p>
<p>El mesón principal, en un impecable blanco cuarzo, contrasta con el elegante salpicadero de efecto mármol. Como punto focal, se destaca un práctico mesón auxiliar tipo barra que extiende el área de trabajo y crea un espacio perfecto para desayunos o comidas rápidas, uniendo el diseño y la convivencia.</p>', '["cocina-integral-minimalista.webp"]', 1, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocinas-integrales-en-alto-brillo', 'Cocinas integrales en alto brillo', '<p>Diseño moderno y elegante con superficies de alto brillo que aportan amplitud, luminosidad y un acabado sofisticado al espacio. Muebles de líneas limpias y minimalistas, sin manijas visibles, para lograr una apariencia uniforme y contemporánea.</p>
<p>Una propuesta funcional y personalizada que combina estética, aprovechamiento del espacio y acabados de alta calidad, ideal para cocinas modernas y elegantes.</p>', '["cocina-integral-alto-brillo.webp"]', 2, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocinas-con-perfil-manija-interna-gola-y-graf', 'Cocinas con perfil manija interna, gola y graf', '<p>Las cocinas con perfil, manija interna, gola y graf combinan diseño y funcionalidad para ofrecer un estilo moderno y minimalista. Estas características permiten un acabado elegante y limpio, eliminando la necesidad de tiradores externos y optimizando el espacio.</p>
<p>Gracias a la integración de perfiles ergonómicos y sistemas de apertura innovadores, logramos cocinas prácticas, cómodas y visualmente sofisticadas, adaptadas a las tendencias contemporáneas.</p>', '["cocinas-integrales-con-perfil-manija-interna-gola-y-graf-2.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-4.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-1.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-3.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-5.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-6.webp", "cocinas-integrales-con-perfil-manija-interna-gola-y-graf-7.webp"]', 3, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocinas-en-pintura-de-poliuretano-o-poliester', 'Cocinas en pintura de poliuretano o poliéster', '<p>Nuestras cocinas en pintura de poliuretano o poliéster destacan por su acabado liso, brillante y resistente. Estos recubrimientos de alta calidad ofrecen una excelente durabilidad, protección contra la humedad y un mantenimiento sencillo. </p>
<p>Disponibles en una amplia gama de colores, permiten crear espacios modernos y elegantes con un acabado sofisticado y duradero.</p>', '["cocinas-integrales-en-pintura-de-poliuretano-4.webp", "cocinas-integrales-en-pintura-de-poliuretano-2.webp", "cocinas-integrales-en-pintura-de-poliuretano-1.webp", "cocinas-integrales-en-pintura-de-poliuretano-3.webp", "cocinas-integrales-en-pintura-de-poliuretano-5.webp", "cocinas-integrales-en-pintura-de-poliuretano-6.webp"]', 4, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocinas-en-tablex-enchapado-en-formica-con-canto-rigido', 'Cocinas en tablex enchapado en fórmica con canto rígido', '<p>Nuestras cocinas en tablex enchapado en fórmica con canto rígido ofrecen una combinación ideal de resistencia y estilo. La fórmica proporciona un acabado duradero y fácil de limpiar, mientras que el canto rígido asegura mayor protección y una apariencia sólida y elegante. Perfectas para quienes buscan funcionalidad y diseño en su cocina.</p>', '["cocinas-en-tablex-enchapado-en-formica-5.webp", "cocinas-en-tablex-enchapado-en-formica-4.webp", "cocinas-en-tablex-enchapado-en-formica-2.webp", "cocinas-en-tablex-enchapado-en-formica-1.webp", "cocinas-en-tablex-enchapado-en-formica-3.webp", "cocinas-en-tablex-enchapado-en-formica-6.webp", "cocinas-en-tablex-enchapado-en-formica-7.webp"]', 5, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('cocinas', 'cocinas-en-tablex-enchapado-en-formica-con-cantos-en-aluminio-y-canto-rigido', 'Cocinas en tablex enchapado en fórmica con cantos en aluminio y canto rígido.', '<p>Nuestras cocinas en tablex enchapado en fórmica ofrecen una combinación perfecta de resistencia y estilo. Con acabados de alta calidad, los cantos en aluminio y canto rígido brindan durabilidad y un diseño moderno, ideal para espacios funcionales y elegantes. Disfruta de una cocina con materiales resistentes al uso diario, fácil mantenimiento y una estética sofisticada</p>', '["cocinas-en-tablex-formica-cantos-en-auminio-3.webp", "cocinas-en-tablex-formica-cantos-en-auminio-1.webp", "cocinas-en-tablex-formica-cantos-en-auminio-2.webp", "cocinas-en-tablex-formica-cantos-en-auminio-4.webp", "cocinas-en-tablex-formica-cantos-en-auminio-5.webp", "cocinas-en-tablex-formica-cantos-en-auminio-6.webp"]', 6, NULL, NULL, '');

INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('productos', 'exhibidores-y-escritorios', 'Exhibidores y escritorios', '<p>Nuestros exhibidores y escritorios están diseñados para brindar organización, funcionalidad y estilo en cualquier espacio. Cada pieza está pensada para optimizar el almacenamiento y la disposición de los elementos, permitiendo una exhibición atractiva y una distribución eficiente. </p>
<p>Con materiales de alta calidad y acabados modernos, garantizan durabilidad y resistencia al uso diario. Ya sea para entornos comerciales, oficinas o el hogar, nuestros diseños se adaptan a diferentes necesidades, asegurando comodidad y practicidad sin comprometer la estética. Una solución ideal para mantener todo en su lugar con un toque sofisticado y ordenado.</p>', '["exhibidores-y-escritorios-1-min.webp", "exhibidores-y-escritorios-3.webp", "exhibidores-y-escritorios-2.webp", "exhibidores-y-escritorios-4.webp", "exhibidores-y-escritorios-5.webp", "exhibidores-y-escritorios-6.webp"]', 1, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('productos', 'closets-en-madecor', 'Closets en madecor', '<p>Nuestros<strong> closets en Madecor</strong> combinan resistencia, funcionalidad y diseño moderno. Gracias a su acabado de alta calidad, ofrecen una estética elegante y una gran durabilidad. </p>
<p>Son ideales para optimizar el espacio de almacenamiento, proporcionando soluciones prácticas y personalizadas para cada necesidad. </p>
<p>Además, su superficie es <strong>fácil de limpiar y mantener</strong>, asegurando un look impecable por más tiempo.</p>', '["closets-en-madecor-1.webp", "closets-en-madecor-2.webp", "closets-en-madecor-4.webp", "closets-en-madecor-6.webp", "closets-en-madecor-7.webp", "closets-en-madecor-8.webp"]', 2, NULL, NULL, '');
INSERT INTO catalogo (tipo, slug, titulo, descripcion, galeria, orden, precio, precio_descuento, nota) VALUES ('productos', 'muebles-de-bano-en-tablex-rh-enchapado-en-formica', 'Muebles de baño en tablex RH enchapado en fórmica', '<p>Nuestros muebles de baño en Tablex RH enchapado en fórmica ofrecen resistencia, durabilidad y un diseño sofisticado. Gracias a su material de alta resistencia a la humedad, son ideales para espacios con alta exposición al agua, garantizando una larga vida útil sin deformaciones. </p>
<p>El acabado en fórmica aporta un toque elegante y moderno, además de facilitar la limpieza y el mantenimiento. Una opción perfecta para combinar funcionalidad y estilo en tu baño.</p>', '["muebles-de-bano-en-tablex-rh-2.webp", "muebles-de-bano-en-tablex-rh-6.webp", "muebles-de-bano-en-tablex-rh-1.webp", "muebles-de-bano-en-tablex-rh-7.webp", "muebles-de-bano-en-tablex-rh-3.webp", "muebles-de-bano-en-tablex-rh-4.webp", "muebles-de-bano-en-tablex-rh-5.webp"]', 3, NULL, NULL, '');

